def minimum_bounded_partition(s,k):
    pieces=0;start=0
    while start<len(s):
        value=0;end=start
        while end<len(s) and value*10+int(s[end])<=k:
            value=value*10+int(s[end]);end+=1
        if end==start:return -1
        pieces+=1;start=end
    return pieces

